const rawText = $json.text || $json.body?.text || $json.body?.message || '';

if (!rawText || !rawText.trim()) {
  return [];
}

const now = new Date();
const cairoDate = new Date(now.toLocaleString('en-US', { timeZone: 'Africa/Cairo' }));

const formatDate = (d) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
};

const daysArabic = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];

const d0 = new Date(cairoDate);
const todayStr = formatDate(d0);
const todayName = daysArabic[d0.getDay()];

const d1 = new Date(cairoDate);
d1.setDate(d1.getDate() + 1);
const tomorrowStr = formatDate(d1);
const tomorrowName = daysArabic[d1.getDay()];

const d2 = new Date(cairoDate);
d2.setDate(d2.getDate() + 2);
const afterTomorrowStr = formatDate(d2);
const afterTomorrowName = daysArabic[d2.getDay()];

const rawPhone = $json.realPhone || $json.phone || $json.body?.phone || '';
let cleanPhone = rawPhone.replace(/@.*/, '').replace(/[^0-9]/g, '');
if (cleanPhone.startsWith('20') && cleanPhone.length === 12) {
  cleanPhone = '0' + cleanPhone.substring(2);
}
const isRealPhone = cleanPhone.startsWith('01') && cleanPhone.length === 11;
const pushName = $json.pushName || $json.body?.pushName || 'العميل';

const phoneInfo = isRealPhone ? `رقم هاتف العميل الحالي هو (${cleanPhone})` : 'رقم هاتف العميل غير محدد صراحة (يرجى التأكد من رقم هاتفه)';

const metadataContext = `[معلومات الجلسة: ${phoneInfo} | اسم حساب الواتساب: (${pushName})]`;
const dateContext = `[تقويم مصر: اليوم هو ${todayName} ${todayStr} | غداً هو ${tomorrowName} ${tomorrowStr} | بعد غد هو ${afterTomorrowName} ${afterTomorrowStr}]`;

return [{
  json: {
    sessionId: cleanPhone || $json.remoteJid || 'default_user',
    customerPhone: isRealPhone ? cleanPhone : '',
    customerName: pushName,
    chatInput: `${metadataContext}\n${dateContext}\nرسالة العميل: ${rawText.trim()}`
  }
}];
